import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import { apiClient, unwrap, type BffResponse } from '../../services/api';
import type { PagedResult } from '../../services/kt/models';
import {
  SEARCH_DROPDOWN_CODE_WIDTH,
  SEARCH_DROPDOWN_PORTAL,
  SEARCH_DROPDOWN_PRIMARY_WIDTH,
} from './searchDropdownDefaults';

/** HR employee row — GET /hr/employees. */
export interface EmployeeLookupItem {
  id: string;
  code: string;
  fullName: string;
  email?: string | null;
  companyCode?: string | null;
  isActive?: boolean;
}

interface EmployeeApiRow {
  id: string;
  code: string;
  fullName: string;
  email?: string | null;
  companyCode?: string | null;
  isActive?: boolean;
}

async function searchEmployees(params: {
  search?: string;
  page: number;
  pageSize: number;
}): Promise<{ items: EmployeeLookupItem[]; page: number; totalPages: number }> {
  const qs = new URLSearchParams({
    page: String(params.page),
    pageSize: String(params.pageSize),
  });
  if (params.search?.trim()) qs.set('search', params.search.trim());
  qs.set('isActive', 'true');

  const res = await apiClient.get<BffResponse<PagedResult<EmployeeApiRow> | EmployeeApiRow[]>>(
    `/hr/employees?${qs.toString()}`,
  );
  const data = unwrap(res);
  const itemsRaw = Array.isArray(data) ? data : (data?.items ?? []);
  const totalCount = Array.isArray(data)
    ? itemsRaw.length
    : Number(data?.totalCount ?? itemsRaw.length);
  const totalPages = Math.max(1, Math.ceil(totalCount / Math.max(1, params.pageSize)));

  return {
    items: itemsRaw.map(e => ({
      id: e.id,
      code: e.code,
      fullName: e.fullName,
      email: e.email,
      companyCode: e.companyCode,
      isActive: e.isActive,
    })),
    page: params.page,
    totalPages,
  };
}

/** SearchInput — dm nhân viên (mã NV + họ tên). GAP-IMP-VOUCHER-13. */
export function createEmployeeSearchConfig(): SearchInputConfig<EmployeeLookupItem> {
  return {
    api: {
      getItemKey: e => e.id || e.code,
      search: ({ search, page, pageSize }) =>
        searchEmployees({ search, page, pageSize: pageSize ?? 20 }),
    },
    display: {
      getPrimaryDisplay: e => e.code,
      getSecondaryDisplay: e => e.fullName,
      getSingleDisplay: e => {
        const code = (e.code || '').trim();
        const name = (e.fullName || '').trim();
        if (code && name) return `${code} — ${name}`;
        return code || name;
      },
    },
    columns: [
      { key: 'code', variant: 'badge', width: SEARCH_DROPDOWN_CODE_WIDTH, render: e => e.code },
      {
        key: 'name',
        variant: 'primary',
        width: SEARCH_DROPDOWN_PRIMARY_WIDTH,
        render: e => e.fullName,
      },
    ],
    header: {
      columns: [
        { key: 'code', label: 'Mã NV' },
        { key: 'name', label: 'Họ tên' },
      ],
    },
    texts: {
      empty: 'Không tìm thấy nhân viên',
    },
    ...SEARCH_DROPDOWN_PORTAL,
  };
}

/**
 * Map user đăng nhập → NV (claim `employeeCode` · email · username).
 * Trả null nếu không match — user chọn tay qua SearchInput.
 */
export async function resolveEmployeeFromAuthUser(auth: {
  employeeCode?: string | null;
  email?: string | null;
  username?: string | null;
  fullName?: string | null;
} | null | undefined): Promise<EmployeeLookupItem | null> {
  if (!auth) return null;

  const claimCode = (auth.employeeCode || '').trim();
  if (claimCode) {
    const byCode = await searchEmployees({ search: claimCode, page: 1, pageSize: 20 });
    const exact = byCode.items.find(
      e => e.code.localeCompare(claimCode, undefined, { sensitivity: 'accent' }) === 0,
    );
    if (exact) return exact;
  }

  const email = (auth.email || '').trim().toLowerCase();
  const username = (auth.username || '').trim().toLowerCase();
  const term = email || username;
  if (!term) return null;

  const result = await searchEmployees({ search: term, page: 1, pageSize: 50 });
  const byEmail = email
    ? result.items.find(e => (e.email || '').trim().toLowerCase() === email)
    : undefined;
  if (byEmail) return byEmail;

  if (username) {
    const byUser = result.items.find(
      e => e.code.toLowerCase() === username
        || (e.fullName || '').toLowerCase().includes(username),
    );
    if (byUser) return byUser;
  }

  return result.items.length === 1 ? result.items[0] : null;
}
